function updateWretch(e,dt){
 const p=player, ang=Math.atan2(p.y-e.y,p.x-e.x), d=Math.hypot(...);
 if(e.state!=='lunge') e.angle = lerpAngle(e.angle,ang,1-Math.exp(-10*dt));
 if(e.state==='windup'){ e.stateT-=dt; if(e.stateT<=0){ e.state='lunge'; e.stateT=.22; e.lungeHit=false; const lv=...; e.lvx=Math.cos(e.angle)*520; e.lvy=...; Sfx.growl? } return; }
 if(e.state==='lunge'){
   e.x+=e.lvx*dt; e.y+=e.lvy*dt; e.stateT-=dt;
   if(!e.lungeHit && d < e.r+p.r+4){ damagePlayer(e.damage*1.05,e.angle); e.lungeHit=true; }
   if(e.stateT<=0){ e.state='recover'; e.stateT=.45; }
   return;
 }
 if(e.state==='recover'){ e.stateT-=dt; if(e.stateT<=0){e.state='idle'; e.atkCd=rand(.7,1.2);} return; }
