}

function drawEnemy(e) {
  const scale = e.r / ENEMY_TYPES[e.type].r;
  const spawnAlpha = e.state === 'spawn' ? clamp(1 - e.spawnT / 0.72, 0, 1) : 1;
  if (spawnAlpha <= 0.02) return;

