  ctx.fillStyle = '#1a2a3a';
  ctx.beginPath();
  ctx.moveTo(-12, -13);
  ctx.quadraticCurveTo(-23, -5, -17, 9);
  ctx.quadraticCurveTo(-6, 14, 4, 10);
  ctx.lineTo(4, -10);
  ctx.quadraticCurveTo(-4, -16, -12, -13);
  ctx.closePath();
