  // torso
  const bodyG = ctx.createLinearGradient(-10, -12, 10, 12);
  bodyG.addColorStop(0, '#33546b');
  bodyG.addColorStop(0.55, '#1c3245');
  bodyG.addColorStop(1, '#0d1724');
